    double c, n_cross, angle;
    size_t i, j;

    if ((c_bi == NULL) || (check_body == NULL) || (check_inertial == NULL) ||
        (angle_residual_rad == NULL) || (cross_residual_body == NULL))
        return ADCS_E_NULL;

    *angle_residual_rad = INFINITY;
    *cross_residual_body = (adcs_vec3_t){0.0, 0.0, 0.0};

    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++)
            if (!isfinite(c_bi->m[i][j]))
                return ADCS_E_NOT_FINITE;

    if ((!adcs_is_finite_vec3(check_body)) || (!adcs_is_finite_vec3(check_inertial)))
        return ADCS_E_RANGE;

    if (adcs_vec3_normalize(check_inertial, ADCS_EPS_NORM, &in_unit) != ADCS_OK)
        return ADCS_E_RANGE;

    mapped = adcs_mat3_mul_vec(c_bi, &in_unit);

    if (adcs_vec3_normalize(&mapped, ADCS_EPS_NORM, &p_unit) != ADCS_OK)
        return ADCS_E_RANGE;

    if (adcs_vec3_normalize(check_body, ADCS_EPS_NORM, &b_unit) != ADCS_OK)
        return ADCS_E_RANGE;

    c = ADCS_CLAMP(adcs_vec3_dot(&b_unit, &p_unit), -1.0, 1.0);
    cross = adcs_vec3_cross(&b_unit, &p_unit);
    n_cross = adcs_vec3_norm(&cross);
    angle = atan2(n_cross, c);

    *angle_residual_rad = angle;
    *cross_residual_body = cross;

    return ADCS_OK;
}
}

